			-------------------------------------------------------------------------------------------------------------
				INSERT INTO #SCP_XLS_PSI_GLOBAL_ELECTRODE WITH (TABLOCK)
				SELECT    A.DIVISION_ID														
						, @p_plan_start_yyyymmdd AS PLAN_START_YYYYMMDD
						, @p_plan_type           AS PLAN_TYPE
						, @p_seq                 AS SEQ
						, A.CELL_TYPE_GROUP_CODE						
						, A.NICK_NAME
						, A.ELECTRODE_TYPE
						, A.ITEM_ID						
						, A.FROM_SITE_ID 
						, ISNULL((SELECT TOP 1 M.SITE_DESCRIPTION FROM SCM_MST_SITE M  WITH (NOLOCK) WHERE M.SCM_SITE_ID=A.FROM_SITE_ID), '-') AS FROM_SITE_DESCRIPTION	
						, A.TO_SITE_ID 
						, ISNULL((SELECT TOP 1 M.SITE_DESCRIPTION FROM SCM_MST_SITE M  WITH (NOLOCK) WHERE M.SCM_SITE_ID=A.TO_SITE_ID), '-') AS TO_SITE_DESCRIPTION	
						, A.LT_WEEK
						, A.CONVERT_QTY_CELL					
						, ISNULL(A.PROD_LINE,'-') AS PROD_LINE
						, A.PSI_TYPE
						, A.MEASURE
						, A.MEASURE_LABEL
						, A.MEASURE_VALUE1
						, A.MEASURE_VALUE1_LABEL 
						, A.MEASURE_VALUE2
						, A.MEASURE_VALUE2_LABEL 
						, A.UNIT
						, A.CELL_ITEM_ID				
						, NULL AS BOH
						, CONVERT(NVARCHAR(200), NULL)  AS XLS_KEY1
						, CONVERT(NVARCHAR(200), NULL)  AS XLS_ATTRIBUTE1
						, A.SORT_ORDER_NO								
               			, A.ORIGIN_FROM_DIVISION_ID 	
						, A.ORIGIN_TO_DIVISION_ID 
