				 WHERE A.YYYYMMDD BETWEEN @p_create_from_yyyymmdd AND @p_create_to_yyyymmdd 
				 GROUP BY A.DIVISION_ID							
	                    , A.CELL_TYPE_GROUP_CODE						
                        , A.NICK_NAME
                        , A.ELECTRODE_TYPE
                        , A.ITEM_ID						
                        , A.FROM_SITE_ID                                             
                        , A.TO_SITE_ID                                             
                        , A.LT_WEEK
	                    , A.CONVERT_QTY_CELL
                        , ISNULL(A.PROD_LINE,'-') 
                        , A.PSI_TYPE
                        , A.MEASURE
                        , A.MEASURE_LABEL
                        , A.MEASURE_VALUE1
                        , A.MEASURE_VALUE1_LABEL 
                        , A.MEASURE_VALUE2
                        , A.MEASURE_VALUE2_LABEL 
                        , A.UNIT
                        , A.CELL_ITEM_ID				
                        , A.SORT_ORDER_NO
                        , A.ORIGIN_FROM_DIVISION_ID
                        , A.ORIGIN_TO_DIVISION_ID 
--                                            , A.ATTRIBUTE7
                        , A.ATTRIBUTE8
                        , A.ATTRIBUTE9
						;
	
 
			-------------------------------------------------------------------------------------------------------------
			-- 튜닝적용: 0 값이 아닌 것은 #tmp_NON_ZERO 에 생성한다.
			-------------------------------------------------------------------------------------------------------------  
			       
            --  364일 데이터 생성(PIVOIT 대상 날짜문자열 생성)         
              DECLARE @mQry_sum NVARCHAR(MAX);      
   
		          SET     @mQry_sum = '';
		          SELECT  @mQry_sum = @mQry_sum+','+       
			          CASE  
                      WHEN 1 = 1 THEN  ' SUM(CASE WHEN YYYYMMDD = '''+YYYYMMDD+'''    THEN ISNULL(QTY, 0) ELSE 0 END ) AS ' + 'QTY' + REPLICATE('0', 3 - LEN(ROW_NUMBER() OVER(ORDER BY YYYYMMDD) )) + CONVERT(NVARCHAR,ROW_NUMBER() OVER(ORDER BY YYYYMMDD))        
			          END +''+CHAR(10)      
		          FROM (       
			          SELECT A.BASIS_YYYYMMDD                    AS YYYYMMDD    
                      , A.BASIS_YYYYMMDD + CONVERT(CHAR(2), 31) AS SORT_ORDER_NO      
  	  	          FROM DBO.SCM_SYS_CALENDAR_M A  WITH(NOLOCK)	     
	 		           WHERE A.BASIS_YYYYMMDD     >= @p_create_from_yyyymmdd 
                   AND A.BASIS_YYYYMMDD     <=  @p_create_to_yyyymmdd     
			           GROUP BY A.BASIS_YYYYMMDD       
		          ) AS A      
		          ORDER BY SORT_ORDER_NO  ;      

              DECLARE @mEXEC NVARCHAR(MAX);

		      SET @mEXEC = '';
              SET @mEXEC = @mEXEC + ' INSERT INTO #tmp_NON_ZERO WITH (TABLOCK)  '+CHAR(10);	

		          SET @mEXEC = @mEXEC + ' SELECT A.DIVISION_ID														
                                            , ''' + @p_plan_start_yyyymmdd +'''	  AS PLAN_START_YYYYMMDD
                                            , ''' + @p_plan_type +'''	            AS PLAN_TYPE
                                            , ''' + @p_seq +'''	                  AS SEQ
                              		        , A.CELL_TYPE_GROUP_CODE						
                              		        , A.NICK_NAME
                                            , A.ELECTRODE_TYPE
                                            , A.ITEM_ID						
                                            , A.FROM_SITE_ID 
                                            , ''-'' AS  FROM_SITE_DESCRIPTION	
                                            , A.TO_SITE_ID 
                                            , ''-'' AS  TO_SITE_DESCRIPTION	
                                            , A.LT_WEEK
                              		        , A.CONVERT_QTY_CELL					
                                            , ISNULL(A.PROD_LINE,''-'') AS      PROD_LINE
                                            , A.PSI_TYPE
                              		        , A.MEASURE
                                            , A.MEASURE_LABEL
                                            , A.MEASURE_VALUE1
                                            , A.MEASURE_VALUE1_LABEL 
                                            , A.MEASURE_VALUE2
                                            , A.MEASURE_VALUE2_LABEL 
                                            , A.UNIT
                                            , A.CELL_ITEM_ID				
                                            , NULL AS BOH
                                            , CONVERT(NVARCHAR(200), NULL)  AS XLS_KEY1
                                            , CONVERT(NVARCHAR(200), NULL)  AS XLS_ATTRIBUTE1
                                            , A.SORT_ORDER_NO								
               		                        , A.ORIGIN_FROM_DIVISION_ID '+CHAR(10);	
              SET @mEXEC = @mEXEC + '       , A.ORIGIN_TO_DIVISION_ID   '+CHAR(10);	
		      SET @mEXEC = @mEXEC + ' 				' + @mQry_sum +'					'+CHAR(10);	
		      SET @mEXEC = @mEXEC + '       , 0 AS ATTRIBUTE1'+CHAR(10);	
              SET @mEXEC = @mEXEC + '       , NULL AS ATTRIBUTE2        '+CHAR(10);	
              SET @mEXEC = @mEXEC + '       , NULL AS ATTRIBUTE3, NULL AS ATTRIBUTE4, NULL AS ATTRIBUTE5, NULL AS ATTRIBUTE6, 0 AS ATTRIBUTE7, ATTRIBUTE8'+CHAR(10);	
              SET @mEXEC = @mEXEC + '       , A.ATTRIBUTE9, NULL AS ATTRIBUTE10    '+CHAR(10);	
  	          SET @mEXEC = @mEXEC + '   FROM #PSI_GLOBAL A WITH (NOLOCK)		       '+CHAR(10);
			  SET @mEXEC = @mEXEC + '  WHERE (A.YYYYMMDD BETWEEN ''' + @p_create_from_yyyymmdd  + ''' AND ''' + @p_create_to_yyyymmdd + ''') '+CHAR(10);		-- 52 구간별 처리
	          SET @mEXEC = @mEXEC + '    AND A.QTY IS NOT NULL
										 AND A.QTY <> 0
									   GROUP BY  A.DIVISION_ID							
	                            			, A.CELL_TYPE_GROUP_CODE						
                              		        , A.NICK_NAME
                                            , A.ELECTRODE_TYPE
                                            , A.ITEM_ID						
                                            , A.FROM_SITE_ID                                             
                                            , A.TO_SITE_ID                                             
                                            , A.LT_WEEK
	                                        , A.CONVERT_QTY_CELL
                                            , ISNULL(A.PROD_LINE,''-'') 
                              		        , A.PSI_TYPE
                              		        , A.MEASURE
                                            , A.MEASURE_LABEL
                                            , A.MEASURE_VALUE1
                                            , A.MEASURE_VALUE1_LABEL 
                                            , A.MEASURE_VALUE2
                                            , A.MEASURE_VALUE2_LABEL 
                                            , A.UNIT
                                            , A.CELL_ITEM_ID				
                                            , A.SORT_ORDER_NO
                                            , A.ORIGIN_FROM_DIVISION_ID
                                            , A.ORIGIN_TO_DIVISION_ID 
--                                          , A.ATTRIBUTE7
                                            , A.ATTRIBUTE8
                                            , A.ATTRIBUTE9
                        '+CHAR(10);

            EXEC sp_executesql @mEXEC;



