				AND ISNULL(M1.CELL_ITEM_ID,            '***') = ISNULL(M2.CELL_ITEM_ID, '***')
				AND ISNULL(M1.SORT_ORDER_NO,          - 9999) = ISNULL(M2.SORT_ORDER_NO, - 9999)
