	          IF OBJECT_ID('tempdb..#CALENDAR') IS NOT NULL	
	            DROP TABLE #CALENDAR

	            SELECT 'D_'+A.BASIS_YYYYMMDD   AS D_YYYYMMDD
                      ,'QTY' + REPLICATE('0', 3 - LEN(ROW_NUMBER() OVER(ORDER BY BASIS_YYYYMMDD) )) + CONVERT(NVARCHAR,ROW_NUMBER() OVER(ORDER BY BASIS_YYYYMMDD)) AS YYYYMMDD_COLUMN
                      , MAX('W_' + A.BASIS_YYYYMM + ISO_WEEK) AS W_YYYY_WEEK 
                      , MAX('M_' + A.BASIS_YYYYMM) AS M_YYYYMM 
                      , MAX(ISO_WEEK) AS ISO_WEEK 
                      , ROW_NUMBER() OVER (ORDER BY A.BASIS_YYYYMMDD + CONVERT(CHAR(2), 31) ) AS Rn
					            , A.BASIS_YYYYMMDD + CONVERT(CHAR(2), 31) AS SORT_ORDER_NO
                  INTO #CALENDAR
						      FROM DBO.SCM_SYS_CALENDAR_M A
					      WHERE A.BASIS_YYYYMMDD  >= @p_create_from_yyyymmdd 
                            AND A.BASIS_YYYYMMDD  <= @p_create_to_yyyymmdd
					      GROUP BY A.BASIS_YYYYMMDD--,ISO_WEEK--,A.BASIS_YYYYMM,ISO_WEEK

	          IF OBJECT_ID('tempdb..#HEADER') IS NOT NULL	
	            DROP TABLE #HEADER

                  SELECT YYYYMMDD_COLUMN, WEEK_COLUMN, W_YYYY_WEEK,M_YYYYMM,ISO_WEEK, SORT_ORDER_NO, X.Rn
                  INTO #HEADER
                  FROM #CALENDAR X
                  INNER JOIN #Rn Y ON X.Rn = Y.Rn
                  order by x.rn
    
              DECLARE @mQry_sumWeek NVARCHAR(MAX);      
   
                SET @mQry_sumWeek = 'UPDATE X '+CHAR(10)
                SELECT @mQry_sumWeek = @mQry_sumWeek + 'SET '+CHAR(10) 
                SELECT @mQry_sumWeek = @mQry_sumWeek + '' + WSUM + ','+CHAR(10)  
             FROM (SELECT DISTINCT WEEK_COLUMN, WEEK_COLUMN +' = (' + 
                         STUFF((
                              SELECT '+' + YYYYMMDD_COLUMN
                              FROM   #HEADER
                              WHERE  WEEK_COLUMN = A.WEEK_COLUMN
                              ORDER BY SORT_ORDER_NO
                              FOR XML PATH('')
                         ),1,1,'') +')'  AS WSUM
                         , MIN(SORT_ORDER_NO)-1 AS SORT_ORDER_NO
                        FROM  #HEADER AS A
                        GROUP BY WEEK_COLUMN
                        ) A 
                ORDER BY WEEK_COLUMN

              SET @mQry_sumWeek = LEFT(@mQry_sumWeek, LEN(@mQry_sumWeek) -2)
              SELECT @mQry_sumWeek = @mQry_sumWeek + CHAR(10) +   ' FROM SCP_XLS_PSI_GLOBAL_ELECTRODE X WITH (NOLOCK) WHERE X.CREATE_FROM_YYYYMMDD = ''' + @p_create_from_yyyymmdd + ''''+CHAR(10)  -- * 2021.04.30   KSW         PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 버전 추가  

			  SELECT @mQry_sumWeek = @mQry_sumWeek + CHAR(10) +   '  AND X.DIVISION_ID          = ''' + @p_division_id	+ ''''+CHAR(10)			-- 2022.03.23	KSW	GM JV 반영


--              PRINT @mQry_sumWeek
              EXEC sp_executesql @mQry_sumWeek;
                  

                UPDATE X
                  SET X.MEASURE_LABEL = TO_SITE_DESCRIPTION
                 FROM SCP_XLS_PSI_GLOBAL_ELECTRODE X WITH (NOLOCK)
                WHERE X.CREATE_FROM_YYYYMMDD = @p_create_from_yyyymmdd		-- * 2021.06.14   KSW         PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 버전 추가
				  AND X.DIVISION_ID          = @p_division_id				-- 2022.03.23	KSW	GM JV 반영
				  AND X.MEASURE = 'SHIP_PLAN'

                UPDATE X
                SET X.MEASURE_LABEL = ISNULL((SELECT TOP 1 M.SITE_DESCRIPTION FROM SCM_MST_SITE M  WITH (NOLOCK) WHERE M.SCM_SITE_ID = X.FROM_SITE_ID), '-')  
                FROM SCP_XLS_PSI_GLOBAL_ELECTRODE X WITH (NOLOCK)
                WHERE X.CREATE_FROM_YYYYMMDD = @p_create_from_yyyymmdd		-- * 2021.06.14   KSW         PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 버전 추가
				  AND X.DIVISION_ID          = @p_division_id				-- 2022.03.23	KSW	GM JV 반영
				  AND X.MEASURE IN ('PROD_PLAN','PROD_PLAN_AMEND')

            
            -------------------------------------------------------------------------------------------------------------         
            -- 보정
            ------------------------------------------------------------------------------------------------------------- 
                UPDATE X
                  SET X.MEASURE_VALUE1_LABEL = ISNULL((SELECT TOP 1 M.SITE_DESCRIPTION FROM SCM_MST_SITE M  WITH (NOLOCK) WHERE M.SCM_SITE_ID = X.MEASURE_VALUE1), '-') 
                 FROM SCP_XLS_PSI_GLOBAL_ELECTRODE X WITH (NOLOCK)
                WHERE X.CREATE_FROM_YYYYMMDD = @p_create_from_yyyymmdd		-- * 2021.06.14   KSW         PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 버전 추가
				  AND X.DIVISION_ID          = @p_division_id				-- 2022.03.23	KSW	GM JV 반영
				  AND X.MEASURE IN ('ETC_LT','INVENTORY_BOH')

                UPDATE X
                  SET X.MEASURE_VALUE1_LABEL = (CASE WHEN X.MEASURE = 'INVENTORY_TOTAL' THEN 'SUM' ELSE NULL END )
                 FROM SCP_XLS_PSI_GLOBAL_ELECTRODE X WITH (NOLOCK)
                WHERE X.CREATE_FROM_YYYYMMDD = @p_create_from_yyyymmdd		-- * 2021.06.14   KSW         PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 버전 추가
				  AND X.DIVISION_ID          = @p_division_id				-- 2022.03.23	KSW	GM JV 반영
				  AND X.MEASURE IN ('INVENTORY_BALANCE_TOTAL','INVENTORY_TOTAL','ETC_RATE')


                UPDATE X
                  SET X.DIVISION_ID = @p_division_id		-- 2022.03.21 GM JV 반영	'EE' --> @p_division_id
                 FROM SCP_XLS_PSI_GLOBAL_ELECTRODE X WITH (NOLOCK)
				WHERE X.CREATE_FROM_YYYYMMDD = @p_create_from_yyyymmdd		-- * 2021.06.14   KSW         PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 버전 추가
				  AND X.DIVISION_ID          = @p_division_id				-- 2022.03.23	KSW	GM JV 반영



            -------------------------------------------------------------------------------------------------------------         
            -- WORKING_TIME UPDATE pivot 테이블 생성   
            ------------------------------------------------------------------------------------------------------------- 
            IF OBJECT_ID('tempdb..#tmp_SCM_SYS_CALENDAR_M_2') IS NOT NULL	
	              DROP TABLE #tmp_SCM_SYS_CALENDAR_M_2

                SELECT C.BASIS_YYYYMMDD AS YYYYMMDD      
                      ,'QTY' + REPLICATE('0', 3 - LEN(ROW_NUMBER() OVER(ORDER BY BASIS_YYYYMMDD) )) + CONVERT(NVARCHAR,ROW_NUMBER() OVER(ORDER BY BASIS_YYYYMMDD)) AS YYYYMMDD_COLUMN
                  INTO #tmp_SCM_SYS_CALENDAR_M_2
                  FROM SCM_SYS_CALENDAR_M    C WITH(NOLOCK)     
                WHERE 1=1  
                  AND C.BASIS_YYYYMMDD BETWEEN @p_create_from_yyyymmdd AND @p_create_to_yyyymmdd
				  ;

