                      ,X.WQTY47   = Y.QTY323  + Y.QTY324 + Y.QTY325  + Y.QTY326  + Y.QTY327  + Y.QTY328  + Y.QTY329
                      ,X.WQTY48   = Y.QTY330  + Y.QTY331 + Y.QTY332  + Y.QTY333  + Y.QTY334  + Y.QTY335  + Y.QTY336
                      ,X.WQTY49   = Y.QTY337  + Y.QTY338 + Y.QTY339  + Y.QTY340  + Y.QTY341  + Y.QTY342  + Y.QTY343
                      ,X.WQTY50   = Y.QTY344  + Y.QTY345 + Y.QTY346  + Y.QTY347  + Y.QTY348  + Y.QTY349  + Y.QTY350
                      ,X.WQTY51   = Y.QTY351  + Y.QTY352 + Y.QTY353  + Y.QTY354  + Y.QTY355  + Y.QTY356  + Y.QTY357
                      ,X.WQTY52   = Y.QTY358  + Y.QTY359 + Y.QTY360  + Y.QTY361  + Y.QTY362  + Y.QTY363  + Y.QTY364
                    FROM SCP_XLS_PSI_GLOBAL_ELECTRODE X  WITH (NOLOCK)
                    INNER JOIN #PROD_TACT_TIME_PIVOT Y  WITH (NOLOCK)
                      ON 0 = 0
					 AND X.CREATE_FROM_YYYYMMDD = @p_create_from_yyyymmdd		-- * 2021.06.14   KSW         PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 버전 추가
					 AND X.FROM_SITE_ID  = Y.SCM_SITE_ID 
					 AND X.PROD_LINE     = Y.LINE_ID 
					 AND X.ITEM_ID       = Y.ITEM_ID
					 AND X.ATTRIBUTE3    = Y.DIVISION_ID
					 AND X.ATTRIBUTE9    = Y.OPERATION_ID 
                   WHERE X.PLAN_START_YYYYMMDD  = @p_plan_start_yyyymmdd
				     AND X.CREATE_FROM_YYYYMMDD = @p_create_from_yyyymmdd
					 AND X.DIVISION_ID          = @p_division_id				-- 2022.03.23	KSW	GM JV 반영
				     AND X.MEASURE       = 'PROD_TACT_TIME'
				   ;

            -------------------------------------------------------------------------------------------------------------         
            -- LT 계산용 테이블 생성   
            ------------------------------------------------------------------------------------------------------------- 

            IF OBJECT_ID('tempdb..#BOM_LT')    IS NOT NULL	
		            DROP TABLE #BOM_LT

				 --  * 2021.05.10   KSW          PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - (LT 고도화 과제) SCP_MST_BOD --> SCP_MST_BOD_V 으로 변경
				 --  * 2021.08.25   KSW          PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 - SCP_MST_BOD_V --> SCP_MST_BOD_N_V
				 -- 
                 SELECT BODi.DIVISION_ID, BODi.ITEM_ID, BODi.BOD_ID, BODm.FROM_SITE,BODm.TO_SITE
                    ,(ISNULL(BODm.LT_DEPARTURE_INLAND,0)+ISNULL(BODm.LT_WAIT_SHIPPING,0)+ISNULL(BODm.LT_VOYAGE,0)+ISNULL(BODm.LT_LAY_OFF_CLEARANCE,0)+ISNULL(BODm.LT_ARRIVAL_INLAND,0)) AS TOTAL_LT
                  INTO #BOM_LT
                  FROM SCP_MST_BOD_ITEM BODi
                  LEFT JOIN SCP_MST_BOD_N_V BODm
                    ON BODi.BOD_ID = BODm.BOD_ID
                  LEFT JOIN SCP_MST_DISTRIBUTION_ROUTE DIS
                    ON DIS.ROUTE_ID = BODm.ROUTE_ID
                 WHERE 1 = 1
                  AND  BODi.VALID_YN = 'Y'
                  AND (BODi.FROM_YYYYMMDD < @p_create_from_yyyymmdd AND BODi.TO_YYYYMMDD > @p_create_from_yyyymmdd)




              UPDATE X
                 SET X.LT_WEEK              =  ISNULL(Y.TOTAL_LT,0)
                    ,X.MEASURE_VALUE2_LABEL =  ISNULL(Y.TOTAL_LT,0)
                    ,X.MEASURE_VALUE2       =  ISNULL(Y.TOTAL_LT,0)
                FROM SCP_XLS_PSI_GLOBAL_ELECTRODE X WITH (NOLOCK)		
                INNER JOIN #BOM_LT Y WITH (NOLOCK)			
	                ON 0 = 0 	
--	               AND Y.DIVISION_ID = X.ORIGIN_FROM_DIVISION_ID
	                --AND Y.BOD_ID      = X.BOD_ID
	             AND X.CREATE_FROM_YYYYMMDD = @p_create_from_yyyymmdd		-- * 2021.06.14   KSW         PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 버전 추가
				 AND X.DIVISION_ID          = @p_division_id				-- 2022.03.23	KSW	GM JV 반영
				 AND X.FROM_SITE_ID   = Y.FROM_SITE 
                 AND X.MEASURE_VALUE1 = Y.TO_SITE
                 AND X.MEASURE        = 'ETC_LT'
                 AND X.ITEM_ID        = Y.ITEM_ID
               WHERE X.MEASURE        = 'ETC_LT'

              -- LT가 0 일 경우 OPERATION_LT 추가
              IF OBJECT_ID('tempdb..#tmp_OPERATION_LT')    IS NOT NULL	
		            DROP TABLE #tmp_OPERATION_LT

                  SELECT A.DIVISION_ID
                         , A.ITEM_ID
		                     , A.SCM_SITE_ID AS FROM_SITE
		                     , ISNULL(A.LT_DAY,0) AS LT_DAY
                  INTO #tmp_OPERATION_LT
	                FROM SCP_MST_OPERATION_LT A WITH(NOLOCK)
	                JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B WITH(NOLOCK) 
                  ON  B.LOOKUP_TYPE='OPERATION_LT' 
                  AND B.VALID_YN='Y' 
                  AND A.LT_OPERATION=B.SEGMENT1
                    


                 UPDATE X
                 SET X.LT_WEEK              =  ISNULL(X.LT_WEEK,0) + ISNULL(Y.LT_DAY,0)
                    ,X.MEASURE_VALUE2_LABEL =  ISNULL(X.LT_WEEK,0) + ISNULL(Y.LT_DAY,0)
                    ,X.MEASURE_VALUE2       =  ISNULL(X.LT_WEEK,0) + ISNULL(Y.LT_DAY,0)
                FROM SCP_XLS_PSI_GLOBAL_ELECTRODE X WITH (NOLOCK)		
                INNER JOIN #tmp_OPERATION_LT Y WITH (NOLOCK)			
	                ON 0 = 0 	
--	               AND Y.DIVISION_ID = X.ORIGIN_FROM_DIVISION_ID
	                --AND Y.BOD_ID      = X.BOD_ID
				   AND X.CREATE_FROM_YYYYMMDD = @p_create_from_yyyymmdd		-- * 2021.06.14   KSW         PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 버전 추가
				   AND X.DIVISION_ID          = @p_division_id				-- 2022.03.23	KSW	GM JV 반영
	               AND X.FROM_SITE_ID   = Y.FROM_SITE 
                 --AND X.MEASURE_VALUE1 = Y.TO_SITE
                 AND X.MEASURE        = 'ETC_LT'
                 AND X.ITEM_ID        = Y.ITEM_ID
               WHERE X.MEASURE        = 'ETC_LT'

               -- 주차처리 
            UPDATE X
                 SET X.MEASURE_VALUE2_LABEL       =  ISNULL(CONVERT(int, (MEASURE_VALUE2_LABEL)/7) + (CASE WHEN ((MEASURE_VALUE2_LABEL)%7 > 0) THEN 1 ELSE 0 END) ,0)
                FROM SCP_XLS_PSI_GLOBAL_ELECTRODE X WITH (NOLOCK)	
              WHERE X.CREATE_FROM_YYYYMMDD = @p_create_from_yyyymmdd		-- * 2021.06.14   KSW         PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 버전 추가
			    AND X.DIVISION_ID          = @p_division_id				-- 2022.03.23	KSW	GM JV 반영
			    AND X.MEASURE              = 'ETC_LT'
              
                  -- 코드명 대신 코드로 보여주는 걸로 변경
                  UPDATE X
                     SET X.MEASURE_VALUE1_LABEL= X.MEASURE_VALUE1
                    FROM SCP_XLS_PSI_GLOBAL_ELECTRODE X  WITH (NOLOCK)
                   WHERE X.CREATE_FROM_YYYYMMDD = @p_create_from_yyyymmdd		-- * 2021.06.14   KSW         PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 버전 추가
				     AND X.DIVISION_ID          = @p_division_id				-- 2022.03.23	KSW	GM JV 반영
				     AND X.MEASURE        IN ('SHIP_PLAN','PROD_PLAN_AMEND','PROD_TACT_TIME','PROD_WORKING_TIME')

                  -- TACT TIME은 주 SUM 대신 평균으로 처리
                  UPDATE X
                     SET X.WQTY01= X.WQTY01 / 7
                        ,X.WQTY02= X.WQTY02 / 7
                        ,X.WQTY03= X.WQTY03 / 7
                        ,X.WQTY04= X.WQTY04 / 7
                        ,X.WQTY05= X.WQTY05 / 7
                        ,X.WQTY06= X.WQTY06 / 7
                        ,X.WQTY07= X.WQTY07 / 7
                        ,X.WQTY08= X.WQTY08 / 7
                        ,X.WQTY09= X.WQTY09 / 7
                        ,X.WQTY10= X.WQTY10 / 7
                        ,X.WQTY11= X.WQTY11 / 7
                        ,X.WQTY12= X.WQTY12 / 7
                        ,X.WQTY13= X.WQTY13 / 7
                        ,X.WQTY14= X.WQTY14 / 7
                        ,X.WQTY15= X.WQTY15 / 7
                        ,X.WQTY16= X.WQTY16 / 7
                        ,X.WQTY17= X.WQTY17 / 7
                        ,X.WQTY18= X.WQTY18 / 7
                        ,X.WQTY19= X.WQTY19 / 7
                        ,X.WQTY20= X.WQTY20 / 7
                        ,X.WQTY21= X.WQTY21 / 7
                        ,X.WQTY22= X.WQTY22 / 7
                        ,X.WQTY23= X.WQTY23 / 7
                        ,X.WQTY24= X.WQTY24 / 7
                        ,X.WQTY25= X.WQTY25 / 7
                        ,X.WQTY26= X.WQTY26 / 7
                        ,X.WQTY27= X.WQTY27 / 7
                        ,X.WQTY28= X.WQTY28 / 7
                        ,X.WQTY29= X.WQTY29 / 7
                        ,X.WQTY30= X.WQTY30 / 7
                        ,X.WQTY31= X.WQTY31 / 7
                        ,X.WQTY32= X.WQTY32 / 7
                        ,X.WQTY33= X.WQTY33 / 7
                        ,X.WQTY34= X.WQTY34 / 7
                        ,X.WQTY35= X.WQTY35 / 7
                        ,X.WQTY36= X.WQTY36 / 7
                        ,X.WQTY37= X.WQTY37 / 7
                        ,X.WQTY38= X.WQTY38 / 7
                        ,X.WQTY39= X.WQTY39 / 7
                        ,X.WQTY40= X.WQTY40 / 7
                        ,X.WQTY41= X.WQTY41 / 7
                        ,X.WQTY42= X.WQTY42 / 7
                        ,X.WQTY43= X.WQTY43 / 7
                        ,X.WQTY44= X.WQTY44 / 7
                        ,X.WQTY45= X.WQTY45 / 7
                        ,X.WQTY46= X.WQTY46 / 7
                        ,X.WQTY47= X.WQTY47 / 7
                        ,X.WQTY48= X.WQTY48 / 7
                        ,X.WQTY49= X.WQTY49 / 7
                        ,X.WQTY50= X.WQTY50 / 7
                        ,X.WQTY51= X.WQTY51 / 7
                        ,X.WQTY52= X.WQTY52 / 7
                    FROM SCP_XLS_PSI_GLOBAL_ELECTRODE X  WITH (NOLOCK)
                   WHERE X.CREATE_FROM_YYYYMMDD = @p_create_from_yyyymmdd		-- * 2021.06.14   KSW         PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 버전 추가
				     AND X.DIVISION_ID          = @p_division_id				-- 2022.03.23	KSW	GM JV 반영
				     AND X.MEASURE      IN ('PROD_TACT_TIME')



            -------------------------------------------------------------------------------------------------------------         
            -- 광폭여부 MEASURE_VALUE2_LABEL 반영
            -------------------------------------------------------------------------------------------------------------
                   UPDATE A
                     SET A.MEASURE_VALUE2_LABEL = C.ATTRIBUTE1
                    FROM  SCP_XLS_PSI_GLOBAL_ELECTRODE A WITH (NOLOCK)
                    INNER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C WITH (NOLOCK)
                       ON 0 = 0
                      AND C.LOOKUP_TYPE   = 'ELECTRODE_LINE_WIDE_RATE'
					  AND A.CREATE_FROM_YYYYMMDD = @p_create_from_yyyymmdd		-- * 2021.06.14   KSW         PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 버전 추가
					  AND A.DIVISION_ID          = @p_division_id				-- 2022.03.23	KSW	GM JV 반영
                      AND A.FROM_SITE_ID  = C.SEGMENT1
                      AND A.PROD_LINE     = C.SEGMENT4
                      AND A.MEASURE       = 'PROD_TACT_TIME'

            -------------------------------------------------------------------------------------------------------------         
            -- ETC_YIELD 보정
            -------------------------------------------------------------------------------------------------------------
                  DELETE
                    FROM SCP_XLS_PSI_GLOBAL_ELECTRODE  
                   WHERE 0 = 0
				     AND CREATE_FROM_YYYYMMDD = @p_create_from_yyyymmdd		-- * 2021.06.14   KSW         PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 버전 추가
					 AND DIVISION_ID          = @p_division_id				-- 2022.03.23	KSW	GM JV 반영
                     AND MEASURE_VALUE1 ='-'
                     AND MEASURE ='ETC_YIELD'


                  DELETE
                    FROM SCP_XLS_PSI_GLOBAL_ELECTRODE  
                   WHERE 0 = 0
                     AND CREATE_FROM_YYYYMMDD = @p_create_from_yyyymmdd		-- * 2021.06.14   KSW         PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 버전 추가
					 AND DIVISION_ID          = @p_division_id				-- 2022.03.23	KSW	GM JV 반영
					 AND MEASURE_VALUE1 ='-'
                     AND MEASURE ='ETC_LT'

                  DELETE TBL 
                    FROM
	                  (
	                          SELECT
                                    ROW_NUMBER() OVER (PARTITION BY DIVISION_ID,NICK_NAME,ELECTRODE_TYPE,ITEM_ID,FROM_SITE_ID,TO_SITE_ID,PROD_LINE,CELL_ITEM_ID,MEASURE,MEASURE_VALUE1,MEASURE_VALUE2
                                    ORDER BY ATTRIBUTE1) AS ROWNUM
	                            FROM SCP_XLS_PSI_GLOBAL_ELECTRODE
                              WHERE 0 = 0
							    AND CREATE_FROM_YYYYMMDD = @p_create_from_yyyymmdd		-- * 2021.06.14   KSW         PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 버전 추가
								AND DIVISION_ID          = @p_division_id				-- 2022.03.23	KSW	GM JV 반영
                                AND MEASURE ='ETC_YIELD'
	                  ) AS TBL
	                  WHERE TBL.ROWNUM > 1


                 DELETE TBL 
                  FROM
	                (
	                        SELECT
	                               ROW_NUMBER() OVER (PARTITION BY MEASURE,CELL_ITEM_ID, ITEM_ID,FROM_SITE_ID,PROD_LINE  
                                                        ORDER BY (WQTY01+WQTY02+WQTY03+WQTY04+WQTY05+WQTY06+WQTY07+WQTY08+WQTY09+WQTY10+
                                                                  WQTY11+WQTY12+WQTY13+WQTY14+WQTY15+WQTY16+WQTY17+WQTY18+WQTY19+WQTY20+
                                                                  WQTY21+WQTY22+WQTY23+WQTY24+WQTY25+WQTY26+WQTY27+WQTY28+WQTY29+WQTY30+
                                                                  WQTY31+WQTY32+WQTY33+WQTY34+WQTY35+WQTY36+WQTY37+WQTY38+WQTY39+WQTY40+
                                                                  WQTY41+WQTY42+WQTY43+WQTY44+WQTY45+WQTY46+WQTY47+WQTY48+WQTY49+WQTY50+
                                                                  WQTY51+WQTY52) desc) AS ROWNUM
                                 --,*
	                        FROM SCP_XLS_PSI_GLOBAL_ELECTRODE
                          WHERE CREATE_FROM_YYYYMMDD = @p_create_from_yyyymmdd		-- * 2021.06.14   KSW         PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 버전 추가
						    AND DIVISION_ID          = @p_division_id				-- 2022.03.23	KSW	GM JV 반영
						    AND MEASURE IN ('PROD_PLAN_AMEND','PROD_TACT_TIME','PROD_WORKING_TIME')
                          --AND ITEM_ID --='APCAN1224A'
	                ) AS TBL
	                WHERE TBL.ROWNUM > 1


               



