                      ,X.WQTY26   = (Y.QTY176  + Y.QTY177 + Y.QTY178  + Y.QTY179  + Y.QTY180  + Y.QTY181  + Y.QTY182) /7
                      ,X.WQTY27   = (Y.QTY183  + Y.QTY184 + Y.QTY185  + Y.QTY186  + Y.QTY187  + Y.QTY188  + Y.QTY189) /7
                      ,X.WQTY28   = (Y.QTY190  + Y.QTY191 + Y.QTY192  + Y.QTY193  + Y.QTY194  + Y.QTY195  + Y.QTY196) /7
                      ,X.WQTY29   = (Y.QTY197  + Y.QTY198 + Y.QTY199  + Y.QTY200  + Y.QTY201  + Y.QTY202  + Y.QTY203) /7
                      ,X.WQTY30   = (Y.QTY204  + Y.QTY205 + Y.QTY206  + Y.QTY207  + Y.QTY208  + Y.QTY209  + Y.QTY210) /7
                      ,X.WQTY31   = (Y.QTY211  + Y.QTY212 + Y.QTY213  + Y.QTY214  + Y.QTY215  + Y.QTY216  + Y.QTY217) /7
                      ,X.WQTY32   = (Y.QTY218  + Y.QTY219 + Y.QTY220  + Y.QTY221  + Y.QTY222  + Y.QTY223  + Y.QTY224) /7
                      ,X.WQTY33   = (Y.QTY225  + Y.QTY226 + Y.QTY227  + Y.QTY228  + Y.QTY229  + Y.QTY230  + Y.QTY231) /7
                      ,X.WQTY34   = (Y.QTY232  + Y.QTY233 + Y.QTY234  + Y.QTY235  + Y.QTY236  + Y.QTY237  + Y.QTY238) /7
                      ,X.WQTY35   = (Y.QTY239  + Y.QTY240 + Y.QTY241  + Y.QTY242  + Y.QTY243  + Y.QTY244  + Y.QTY245) /7
                      ,X.WQTY36   = (Y.QTY246  + Y.QTY247 + Y.QTY248  + Y.QTY249  + Y.QTY250  + Y.QTY251  + Y.QTY252) /7
                      ,X.WQTY37   = (Y.QTY253  + Y.QTY254 + Y.QTY255  + Y.QTY256  + Y.QTY257  + Y.QTY258  + Y.QTY259) /7
                      ,X.WQTY38   = (Y.QTY260  + Y.QTY261 + Y.QTY262  + Y.QTY263  + Y.QTY264  + Y.QTY265  + Y.QTY266) /7
                      ,X.WQTY39   = (Y.QTY267  + Y.QTY268 + Y.QTY269  + Y.QTY270  + Y.QTY271  + Y.QTY272  + Y.QTY273) /7
                      ,X.WQTY40   = (Y.QTY274  + Y.QTY275 + Y.QTY276  + Y.QTY277  + Y.QTY278  + Y.QTY279  + Y.QTY280) /7
                      ,X.WQTY41   = (Y.QTY281  + Y.QTY282 + Y.QTY283  + Y.QTY284  + Y.QTY285  + Y.QTY286  + Y.QTY287) /7
                      ,X.WQTY42   = (Y.QTY288  + Y.QTY289 + Y.QTY290  + Y.QTY291  + Y.QTY292  + Y.QTY293  + Y.QTY294) /7
                      ,X.WQTY43   = (Y.QTY295  + Y.QTY296 + Y.QTY297  + Y.QTY298  + Y.QTY299  + Y.QTY300  + Y.QTY301) /7
                      ,X.WQTY44   = (Y.QTY302  + Y.QTY303 + Y.QTY304  + Y.QTY305  + Y.QTY306  + Y.QTY307  + Y.QTY308) /7
                      ,X.WQTY45   = (Y.QTY309  + Y.QTY310 + Y.QTY311  + Y.QTY312  + Y.QTY313  + Y.QTY314  + Y.QTY315) /7
                      ,X.WQTY46   = (Y.QTY316  + Y.QTY317 + Y.QTY318  + Y.QTY319  + Y.QTY320  + Y.QTY321  + Y.QTY322) /7
                      ,X.WQTY47   = (Y.QTY323  + Y.QTY324 + Y.QTY325  + Y.QTY326  + Y.QTY327  + Y.QTY328  + Y.QTY329) /7
                      ,X.WQTY48   = (Y.QTY330  + Y.QTY331 + Y.QTY332  + Y.QTY333  + Y.QTY334  + Y.QTY335  + Y.QTY336) /7
                      ,X.WQTY49   = (Y.QTY337  + Y.QTY338 + Y.QTY339  + Y.QTY340  + Y.QTY341  + Y.QTY342  + Y.QTY343) /7
                      ,X.WQTY50   = (Y.QTY344  + Y.QTY345 + Y.QTY346  + Y.QTY347  + Y.QTY348  + Y.QTY349  + Y.QTY350) /7
                      ,X.WQTY51   = (Y.QTY351  + Y.QTY352 + Y.QTY353  + Y.QTY354  + Y.QTY355  + Y.QTY356  + Y.QTY357) /7
                      ,X.WQTY52   = (Y.QTY358  + Y.QTY359 + Y.QTY360  + Y.QTY361  + Y.QTY362  + Y.QTY363  + Y.QTY364) /7
                    FROM SCP_XLS_PSI_GLOBAL_ELECTRODE X  WITH (NOLOCK)
                    INNER JOIN #ETC_YIELD_PIVOT Y  WITH (NOLOCK)
                      ON 0 = 0
					 AND X.CREATE_FROM_YYYYMMDD = @p_create_from_yyyymmdd		-- * 2021.06.14   KSW         PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 버전 추가
					 AND X.DIVISION_ID          = @p_division_id				-- 2022.03.23	KSW	GM JV 반영
                     AND X.MEASURE_VALUE2 = Y.ITEM_ID
                     AND X.MEASURE_VALUE1 = Y.PLANT_SITE_ID
                   WHERE X.MEASURE        = 'ETC_YIELD'

                   -- PROD_PLAN_AMEND 없어서 강제로 추가된 DATA 삭제
                   DELETE FROM SCP_XLS_PSI_GLOBAL_ELECTRODE
                    WHERE 0 = 0
					AND CREATE_FROM_YYYYMMDD = @p_create_from_yyyymmdd		-- * 2021.06.14   KSW         PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 버전 추가
					AND DIVISION_ID          = @p_division_id				-- 2022.03.23	KSW	GM JV 반영
                    AND MEASURE IN ('PROD_PLAN_AMEND','PROD_TACT_TIME','PROD_WORKING_TIME')
                    AND PROD_LINE ='-'

                  UPDATE X
                     SET X.UNIT = 'MIN'
                    FROM SCP_XLS_PSI_GLOBAL_ELECTRODE X WITH (NOLOCK)
                    WHERE X.CREATE_FROM_YYYYMMDD = @p_create_from_yyyymmdd		-- * 2021.06.14   KSW         PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 버전 추가
					  AND X.DIVISION_ID          = @p_division_id				-- 2022.03.23	KSW	GM JV 반영  
					  AND X.MEASURE ='PROD_WORKING_TIME'

                  UPDATE X
                     SET X.UNIT = 'JB/M'
                    FROM SCP_XLS_PSI_GLOBAL_ELECTRODE X WITH (NOLOCK)
                    WHERE X.CREATE_FROM_YYYYMMDD = @p_create_from_yyyymmdd		-- * 2021.06.14   KSW         PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 버전 추가
					  AND X.DIVISION_ID          = @p_division_id				-- 2022.03.23	KSW	GM JV 반영
					  AND X.MEASURE ='PROD_TACT_TIME'
 



                -- 
                -- BOH 보정
                --SELECT X.MEASURE_VALUE2 , Y.QTY,ELEC_ITEM_ID
                  UPDATE X
                      SET X.MEASURE_VALUE2 = Y.QTY
                         ,X.MEASURE_VALUE2_LABEL = Y.QTY
                  FROM SCP_XLS_PSI_GLOBAL_ELECTRODE  X  WITH (NOLOCK)
                  INNER JOIN (
                            SELECT ELEC_ITEM_ID
	                             ,FROM_SITE_ID
	                             ,TO_SITE_ID
	                             ,SUM(CONVERT_QTY) AS QTY
                              FROM SCP_XLS_PSI_GLOBAL_ELECTRODE_BOM WITH(NOLOCK)
                             WHERE ELEC_DIVISION_ID = @p_division_id -- [PJ20230691R] LGES SCM 역량 강화 위한 SCP 개선과제 이행 - ELECTRODE_BOM(BOH) 테이블 PK 컬럼 추가 반영 (ELEC_DIVISION_ID : EE/EE_UC)  
                               --AND ELEC_ITEM_ID = 'APCCA0939A'
                               --AND FROM_SITE_ID = 'G383-E'
							   AND AVAILABLE_DATE < convert(date, @p_plan_start_yyyymmdd )		-- C20210702-000348 - 전극 시뮬레이터 내 BOH 보류재고 반영 로직 수정 요청의 건 - 보류재고가 아닌 건
                             GROUP BY 
	                            ELEC_ITEM_ID
	                             ,FROM_SITE_ID
	                             ,TO_SITE_ID
                          ) Y 
                  ON X.ITEM_ID        = Y.ELEC_ITEM_ID
				  AND X.CREATE_FROM_YYYYMMDD = @p_create_from_yyyymmdd		-- * 2021.06.14   KSW         PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 버전 추가
				  AND X.DIVISION_ID          = @p_division_id				-- 2022.03.23	KSW	GM JV 반영
                  AND X.FROM_SITE_ID  = Y.FROM_SITE_ID
                  ANd X.MEASURE_VALUE1= Y.TO_SITE_ID
                  AND X.MEASURE       = 'INVENTORY_BOH'
                  AND X.MEASURE_LABEL = 'BOH'



                -- 2021.07.29 KSW 추가 (보류재고 값을 한번더 업데이트...) - start
                -- BOH 보정
                --SELECT X.MEASURE_VALUE2 , Y.QTY,ELEC_ITEM_ID
                  UPDATE X
                      SET X.MEASURE_VALUE2 = Y.QTY
                         ,X.MEASURE_VALUE2_LABEL = Y.QTY
                  FROM SCP_XLS_PSI_GLOBAL_ELECTRODE  X  WITH (NOLOCK)
                  INNER JOIN (
                            SELECT ELEC_ITEM_ID
	                             ,FROM_SITE_ID
	                             ,SUM(CONVERT_QTY) AS QTY
                              FROM SCP_XLS_PSI_GLOBAL_ELECTRODE_BOM WITH(NOLOCK)
                             WHERE ELEC_DIVISION_ID = @p_division_id -- [PJ20230691R] LGES SCM 역량 강화 위한 SCP 개선과제 이행 - ELECTRODE_BOM(BOH) 테이블 PK 컬럼 추가 반영 (ELEC_DIVISION_ID : EE/EE_UC)  
                               --AND ELEC_ITEM_ID = 'APCAN0019A'
                               --AND FROM_SITE_ID = 'A011-E'
							   AND AVAILABLE_DATE >= convert(date, @p_plan_start_yyyymmdd )		-- C20210702-000348 - 전극 시뮬레이터 내 BOH 보류재고 반영 로직 수정 요청의 건 - 보류재고가 아닌 건
                             GROUP BY 
	                            ELEC_ITEM_ID
	                             ,FROM_SITE_ID
                          ) Y 
                  ON X.ITEM_ID        = Y.ELEC_ITEM_ID
				  AND X.CREATE_FROM_YYYYMMDD = @p_create_from_yyyymmdd		-- * 2021.06.14   KSW         PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 버전 추가
				  AND X.DIVISION_ID          = @p_division_id				-- 2022.03.23	KSW	GM JV 반영
                  AND X.FROM_SITE_ID  = Y.FROM_SITE_ID
                  AND X.MEASURE       = 'INVENTORY_HOLD'
				  -- 2021.07.29 KSW 추가 (보류재고 값을 한번더 업데이트...) - end



                  -- 생산라인 입력 추가 기능(XLS_KEY1 생성로직 변경 XLS_KEY1*1000 )
                  UPDATE X
                    SET X.XLS_KEY1 = XLS_KEY1 * 1000
                  FROM SCP_XLS_PSI_GLOBAL_ELECTRODE X  WITH (NOLOCK)
				 WHERE X.CREATE_FROM_YYYYMMDD = @p_create_from_yyyymmdd		-- * 2021.06.14   KSW         PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 버전 추가
				   AND X.DIVISION_ID          = @p_division_id				-- 2022.03.23	KSW	GM JV 반영

				  --
				  -- DIO 기준/최소 컬럼추가, * GAP_PRE_GRO_DIO, GAP_PRE_MIN_DIO Measure 추가 
				  --
				  IF OBJECT_ID('tempdb..#tmp_SCP_MST_DIO') IS NOT NULL	
					  DROP TABLE #tmp_SCP_MST_DIO

				  SELECT a.DIVISION_ID, a.PLANT_ID, ITEM_ID,a.GRO_STD_DIO,MIN_STD_DIO
					INTO #tmp_SCP_MST_DIO
					FROM   SCP_MST_DIO A WITH(NOLOCK) 
					INNER JOIN (SELECT DIVISION_ID, PLANT_ID, MAX(YYYYQ) AS YYYYQ
								FROM   SCP_MST_DIO WITH(NOLOCK) 
								WHERE  DIVISION_ID IS NOT NULL
								GROUP BY DIVISION_ID, PLANT_ID
							  ) B
					ON  A.DIVISION_ID = B.DIVISION_ID
					AND A.PLANT_ID    = B.PLANT_ID
					AND A.YYYYQ      = B.YYYYQ
					--AND A.DIVISION_ID = @p_division_id
					--and a.YYYYMM      like '201912' -- @p_plan_start_yyyymmdd -- 


				  UPDATE X
					 SET X.ATTRIBUTE4   = Z.GRO_STD_DIO
						,X.ATTRIBUTE5   = Z.MIN_STD_DIO
				   FROM SCP_XLS_PSI_GLOBAL_ELECTRODE X WITH (NOLOCK)
				   INNER JOIN #tmp_SCP_MST_DIO Z  WITH (NOLOCK)
					ON X.ITEM_ID   = Z.ITEM_ID
				   --AND X.FROM_SITE_ID LIKE Z.PLANT_ID + '%'
					WHERE X.CREATE_FROM_YYYYMMDD = @p_create_from_yyyymmdd		-- * 2021.06.14   KSW         PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 버전 추가
					  AND X.DIVISION_ID          = @p_division_id				-- 2022.03.23	KSW	GM JV 반영
					  AND X.MEASURE       = 'INVENTORY_PRE_DIO'
				--*/


        -----------------------------------------------------------      
        -- 실행 Logic END --      
        -----------------------------------------------------------      
        --IF @@TRANCOUNT > 0      
        --  BEGIN      
        --    COMMIT TRAN T1;      
        --  END;             
      
      
        -- TXN LOG      
        SET @v_log_type     = N'TXN';        
        SET @n_log_count    = @@ROWCOUNT;      
        SET @v_log_message  = N'INSERT INTO '+@v_table_id;      
        SET @v_description  = N'Process Complete...' + ':' + CONVERT(CHAR(8), @d_event_date, 112);      
        SET @d_event_date   = SYSDATETIME();      
      
        EXEC PR_SCP_SYS_LOG_BATCH  @p_program_name  = @v_program_name      
                                  ,@p_log_type      = @v_log_type      
                                  ,@p_log_count     = @n_log_count       
                                  ,@p_log_message   = @v_log_message       
                                  ,@p_description   = @v_description       
                                  ,@p_event_date    = @d_event_date       
                                  ,@p_user_id       = @v_batch_user      
                                  ;            
      
    END      
    END TRY      
      
    BEGIN CATCH      
      --IF @@TRANCOUNT > 0      
      --  BEGIN      
      --    ROLLBACK TRAN T1      
      --  END;      
            
      -- ERROR LOG      
      SET @v_log_type     = N'ERROR';      
      SET @v_log_message  = CAST(ERROR_MESSAGE() AS NVARCHAR(1000));      
      SET @v_description  = @v_program_name + N'ERROR_LINE : ' + STR(ERROR_LINE());      
      SET @d_event_date   = SYSDATETIME();      
      EXEC PR_SCP_SYS_LOG_BATCH  @p_program_name  = @v_program_name      
                          ,@p_log_type      = @v_log_type      
                                ,@p_log_count     = @n_log_count       
                                ,@p_log_message   = @v_log_message       
                                ,@p_description   = @v_description       
                                ,@p_event_date    = @d_event_date       
                                ,@p_user_id       = @v_batch_user      
                                ;      
--      PRINT @@ERROR      
      return -1      
    END CATCH;      
      
  
  
     SET @v_exec_time  =  REPLICATE('0',2 - LEN((convert(varchar, (DATEDIFF(second,       @v_start_time, SYSDATETIME())/ 60))) )) + (convert(varchar, (DATEDIFF(second,       @v_start_time, SYSDATETIME())/ 60))) + ':' +     
                          REPLICATE('0',2 - LEN((convert(varchar, (DATEDIFF(second,       @v_start_time, SYSDATETIME()))% 60)) )) + (convert(varchar, (DATEDIFF(second,       @v_start_time, SYSDATETIME()))% 60))     
       
    -- 종료 LOG          
    SET @v_log_type     = N'END';          
    SET @v_log_message  = N'########## END of procedure ##########';          
    SET @v_description  = N'['+@p_master_id+']['+@p_engine_plan_id+'][' + @v_exec_time + ']';                
    SET @d_event_date   = SYSDATETIME()  ;     
    EXEC PR_SCP_SYS_LOG_BATCH  @p_program_name  = @v_program_name      
                              ,@p_log_type      = @v_log_type      
                              ,@p_log_count     = @n_log_count       
                              ,@p_log_message   = @v_log_message       
                              ,@p_description   = @v_description       
                              ,@p_event_date    = @d_event_date       
                              ,@p_user_id       = @v_batch_user      
                              ;      
    return 1        
      
  END;       
  
  


